package com.example.campusmaintenance.dto; import java.time.LocalDateTime;
public class ApiResponse<T>{private boolean success;private String message;private T data;private LocalDateTime timestamp;private String path;private String correlationId; public ApiResponse(){} public ApiResponse(boolean s,String m,T d,String p,String c){success=s;message=m;data=d;path=p;correlationId=c;timestamp=LocalDateTime.now();} public boolean isSuccess(){return success;} public String getMessage(){return message;} public T getData(){return data;} public LocalDateTime getTimestamp(){return timestamp;} public String getPath(){return path;} public String getCorrelationId(){return correlationId;}}
